CREATE TABLE "integration_client" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "client_key" varchar(100) UNIQUE NOT NULL,
    "name" varchar(200) NOT NULL,
    "secret_hash" text NOT NULL,
    "owner_user_id" bigint NOT NULL,
    "is_active" boolean NOT NULL DEFAULT true,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "integration_client_owner_user_id_fkey"
        FOREIGN KEY ("owner_user_id") REFERENCES "user" ("id") ON DELETE RESTRICT
);

CREATE TABLE "integration_client_permission" (
    "client_id" bigint NOT NULL,
    "permission_code" varchar(100) NOT NULL,
    PRIMARY KEY ("client_id", "permission_code"),
    CONSTRAINT "integration_client_permission_client_id_fkey"
        FOREIGN KEY ("client_id") REFERENCES "integration_client" ("id") ON DELETE CASCADE
);

CREATE TABLE "webhook_subscription" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "client_id" bigint NOT NULL,
    "url" text NOT NULL,
    "signing_secret" text NOT NULL,
    "is_active" boolean NOT NULL DEFAULT true,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "webhook_subscription_client_id_fkey"
        FOREIGN KEY ("client_id") REFERENCES "integration_client" ("id") ON DELETE CASCADE,
    CONSTRAINT "webhook_subscription_client_url_key" UNIQUE ("client_id", "url")
);

CREATE TABLE "webhook_subscription_event" (
    "subscription_id" bigint NOT NULL,
    "event_type" varchar(100) NOT NULL,
    PRIMARY KEY ("subscription_id", "event_type"),
    CONSTRAINT "webhook_subscription_event_subscription_id_fkey"
        FOREIGN KEY ("subscription_id") REFERENCES "webhook_subscription" ("id") ON DELETE CASCADE
);

CREATE TABLE "webhook_delivery" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "subscription_id" bigint NOT NULL,
    "event_type" varchar(100) NOT NULL,
    "payload" jsonb NOT NULL,
    "status" varchar(16) NOT NULL DEFAULT 'pending',
    "attempts" integer NOT NULL DEFAULT 0,
    "next_attempt_at" timestamptz NOT NULL DEFAULT now(),
    "response_status" integer,
    "last_error" text,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    "sent_at" timestamptz,
    CONSTRAINT "webhook_delivery_subscription_id_fkey"
        FOREIGN KEY ("subscription_id") REFERENCES "webhook_subscription" ("id") ON DELETE CASCADE,
    CONSTRAINT "webhook_delivery_status_check"
        CHECK ("status" IN ('pending', 'processing', 'sent', 'failed')),
    CONSTRAINT "webhook_delivery_attempts_check" CHECK ("attempts" >= 0)
);

CREATE INDEX "webhook_delivery_pending_idx"
    ON "webhook_delivery" ("next_attempt_at", "id")
    WHERE "status" IN ('pending', 'processing');
